package emixacommons.actions;

import com.mendix.core.Core;
import com.mendix.core.CoreException;
import com.mendix.logging.ILogNode;
import com.mendix.systemwideinterfaces.core.IContext;
import com.mendix.systemwideinterfaces.core.IMendixObject;
import com.mendix.systemwideinterfaces.core.meta.IMetaObject;
import com.mendix.systemwideinterfaces.core.meta.IMetaPrimitive;
import com.mendix.systemwideinterfaces.core.meta.IMetaPrimitive.PrimitiveType;
import com.mendix.systemwideinterfaces.core.UserAction;

/**
 * This java action changes the inputobject with decrypted attribute values for attrbutes where the name of the attribute ends with a _E
 */
public class GetObjectWithDecryptedAttibutes extends UserAction<java.lang.Void>
{
	private final IMendixObject AnyObject;

	public GetObjectWithDecryptedAttibutes(
		IContext context,
		IMendixObject _anyObject
	)
	{
		super(context);
		this.AnyObject = _anyObject;
	}

	@java.lang.Override
	public java.lang.Void executeAction() throws Exception
	{
		// BEGIN USER CODE
		ILogNode logger = Core.getLogger("EmixaCommons");

        if (AnyObject == null) {
            logger.warn("empty object.");
            return null;
        }

        IContext ctx = getContext();
        IMetaObject meta = AnyObject.getMetaObject();

        for (IMetaPrimitive primitive : meta.getMetaPrimitives()) {
            String attrName = primitive.getName();

            if (primitive.getType() == PrimitiveType.String && attrName != null && attrName.endsWith("_E")) {
                String encrypted = (String) AnyObject.getValue(ctx, attrName);

                if (encrypted == null || encrypted.isEmpty()) {
                    continue; 
                }

                try {
                    String decrypted = decryptWithEncryptionModule(ctx, encrypted);
                    if (decrypted != null) {
                        AnyObject.setValue(ctx, attrName, decrypted);
                    } else {
                        logger.warn(String.format("Decrypt empty for '%s' op %s.", attrName, meta.getName() ));
                    }
                } catch (Exception e) {
                    logger.error(String.format("error decrypting '%s' op %s: %s",  attrName, meta.getName(), e.getMessage() ), e);
                }
            }
        }
        return null;

		// END USER CODE
	}

	/**
	 * Returns a string representation of this action
	 * @return a string representation of this action
	 */
	@java.lang.Override
	public java.lang.String toString()
	{
		return "GetObjectWithDecryptedAttibutes";
	}

	// BEGIN EXTRA CODE

/**
     * Roept de standaard Encryption Java action "Encryption.DecryptString" aan.
     * Zorg dat de Encryption module is geïnstalleerd en geconfigureerd.
     */
    private String decryptWithEncryptionModule(IContext ctx, String encrypted) throws CoreException {
        return encryption.proxies.microflows.Microflows.decrypt(ctx, encrypted);
    }

	// END EXTRA CODE
}
